def get_neighbors(c, R):
    cx, cy = c
    neighbors = []
    for dx in range(-(R // 2), (R // 2) + 1):
        for dy in range(-(R // 2), (R // 2) + 1):
            neighbors.append((cx + dx, cy + dy))
    return neighbors

def simulate(n, R, s):
    green = set([(n // 2, n // 2)])

    while True:
        possible_c = []
        for c in green:
            neighbors = get_neighbors(c, R)
            available = [p for p in neighbors if p not in green and 0 <= p[0] < n and 0 <= p[1] < n]
            if len(available) >= s:
                possible_c.append((c, available))

        if not possible_c:
            break

        # To maximize growth, we want to pick c and S such that we expand as much as possible.
        # A simple strategy: pick c that is on the edge and S that is also on the edge.
        # For now, let's just pick the first possible_c and the first s available.
        # This is not maximizing, but let's see.
        c, available = possible_c[0]
        green.update(available[:s])

    return len(green)

