def simulate_aggressive_v2(n, R, s, trials=5):
    max_g = 0
    for _ in range(trials):
        green = set([(n // 2, n // 2)])
        while True:
            possible_c = []
            for c in green:
                neighbors = get_neighbors(c, R)
                available = [p for p in neighbors if p not in green and 0 <= p[0] < n and 0 <= p[1] < n]
                if len(available) >= s:
                    possible_c.append((c, available))
            if not possible_c:
                break

            # To be more aggressive, let's pick a random possible_c and random S
            # Actually, picking S that are on the edge is better.
            c, available = random.choice(possible_c)
            # To expand, pick s cells that are farthest from the center of the grid
            available.sort(key=lambda p: abs(p[0]-n//2) + abs(p[1]-n//2), reverse=True)
            green.update(available[:s])
        max_g = max(max_g, len(green))
    return max_g

